    if(this.panel==='inspect'){const hull=HULL_ASSETS[this.game.inspectShip],status=this.el.panelContent.querySelector('[data-model-status]'),state=hull?.id==='nova-fighter'?this.game.view.fighterStatus:this.game.view.assets.status.get(hull?.id);if(status)status.textContent=state==='ready'?'TEXTURED HULL READY':state==='error'?'MODEL UNAVAILABLE · REFRESH TO RETRY':'LOADING HULL TEXTURES…';}
    el.app.style.setProperty('--system-color',sys.color);el.musicName.textContent=this.game.audio.blocked?'Start music':this.game.audio.musicEnabled===false?'Music off':this.game.audio.trackName||'Music';el.musicBtn.classList.toggle('playing',this.game.audio.started&&this.game.audio.musicEnabled&&!this.game.audio.blocked);el.musicBtn.classList.toggle('muted',this.game.audio.musicEnabled===false);el.musicBtn.classList.toggle('blocked',!!this.game.audio.blocked);el.musicBtn.setAttribute('aria-pressed',String(this.game.audio.musicEnabled!==false));el.flightMode.textContent=this.mode==='departure'?'CLEARING PORT / DRIVE QUEUED':sim.autopilot?'ASSISTED APPROACH':sim.boosting?'BOOST DRIVE ENGAGED':'MANUAL FLIGHT';el.trafficCount.textContent=sim.entities.filter(v=>v.kind==='trader'&&!v.hidden).length+' COMMERCIAL CONTACTS';el.creditCount.textContent=money(this.s.credits);el.locName.textContent=sys.name.toUpperCase();el.locMeta.textContent=sys.faction.toUpperCase()+' / '+(sys.security===0?'UNREGULATED':sys.security===3?'INNER WORLD':'FRONTIER');
    el.shipLabel.textContent=this.s.shipName.toUpperCase();el.shipClass.textContent=ship.name.toUpperCase();
    const meters=[['hull',this.s.hull,ship.hull],['shield',this.s.shield,ship.shield],['power',sim.energy,100]];
    for(const [key,value,max]of meters){el[key+'Bar'].style.width=Math.max(0,value/max*100)+'%';el[key+'Text'].textContent=Math.ceil(value);}
    el.hullBar.style.background=this.s.hull/ship.hull<.3?'var(--red)':'#c4bd91';el.fuelText.textContent=Math.floor(this.s.fuel);el.holdText.textContent=cargoUsed(this.s)+'/'+ship.hold;el.missileText.textContent=this.s.missiles;el.speedText.textContent=Math.round(sim.speed);el.throttleText.textContent=Math.round(sim.throttle*100)+'%';if(document.activeElement!==el.throttle)el.throttle.value=Math.round(sim.throttle*100);
    el.autoBtn.classList.toggle('active',sim.autopilot);el.dockBtn.disabled=!sim.canDock();el.rocketBtn.disabled=this.s.missiles<1;el.boostBtn.classList.toggle('active',sim.boosting);el.fireBtn.classList.toggle('active',sim.input.fire);
    const target=sim.target;if(target){el.targetName.textContent=target.name;el.targetKind.textContent={station:'PORT / FRIENDLY',pirate:'RAIDER / HOSTILE',patrol:'DIRECTORATE / PATROL',ore:'MINERAL BODY / TITANIUM',cache:'SALVAGE / RECOVERABLE',wreck:'CONVOY WRECK / SALVAGE',civilian:'MISSION CONTACT / FRIENDLY',beacon:'BEACON / SCANNER CONTACT',relay:'RELAY / POWER SYSTEM'}[target.kind]||'CONTACT';el.targetDistance.textContent=distance(sim.distance(target));el.targetHealth.textContent=target.hp?'INTEGRITY '+Math.max(0,Math.ceil(target.hp/target.maxHp*100))+'%':'';el.targetKind.style.color=target.kind==='pirate'?'#f19b81':target.kind==='trader'?'#a5cbe0':'var(--teal)';if(target.kind==='civilian'&&target.hp)el.targetHealth.textContent='HULL '+Math.ceil(target.hp/target.maxHp*100)+'% · '+target.phase;if(target.kind==='trader'){el.targetKind.textContent=(target.capital?'CAPITAL SHIP / ':'CIVILIAN / ')+target.classId.toUpperCase();el.targetHealth.textContent=target.phase.toUpperCase();}if(target.interactionComplete){el.targetKind.textContent=target.kind==='beacon'?'WRECK / SCANNED':target.kind==='wreck'?'WRECK / EMPTY':'CIVILIAN / FRIENDLY';el.targetHealth.textContent=(target.hp?'HULL '+Math.ceil(target.hp/target.maxHp*100)+'% · ':'')+target.phase;}}
