    if(this.mode==='departure'){el.missionTitle.textContent='Leaving '+sys.port;el.missionObjective.textContent='Clearing the port · Escape cancels departure';el.objectiveProgress.hidden=false;el.objectiveProgress.firstElementChild.style.width=Math.min(100,sim.pos.length()/sim.jumpClearance()*100)+'%';}
    el.mouseBtn.classList.toggle('active',!!this.game.pointer?.active);el.mouseGuide.hidden=this.mode!=='flight'||!this.game.pointer?.active||this.game.preferences?.mouseMode==='drag'||!!this.panel;
    if(this.touchMode)this.touchHud(mission,encounter,ship,sys);else if(this.mode==='flight')this.radar(time);
